create temporary view traffic_raw_${grass_region_without_quote} as
select *
from srdi_mart.dws_sr_data_warehouse_tc_pb_reward_model_exp_level_1d
where grass_region = ${grass_region}
and local_date between date_sub(${local_date},13) and ${local_date}
;
--sql_divide_splitter--

create temporary view traffic_aggr_${grass_region_without_quote} as
select model_id
    ,item_id
    ,shop_id
    ,sum(case when local_date >= date_sub(${local_date},6) then imp_cnt else 0 end) imp_cnt_l7d
    ,sum(case when local_date >= date_sub(${local_date},6) then gmv else 0 end) gmv_l7d
    ,sum(case when local_date >= date_sub(${local_date},6) and is_win_day = 1 then imp_cnt else 0 end) win_imp_cnt_l7d
    ,sum(case when local_date >= date_sub(${local_date},6) and is_win_day = 1 then gmv else 0 end) win_gmv_l7d
    ,sum(case when local_date >= date_sub(${local_date},6) and is_win_day = 1 then control_imp_cnt else 0 end) win_control_imp_cnt_l7d
    ,sum(case when local_date >= date_sub(${local_date},6) and is_win_day = 1 then control_gmv else 0 end) win_control_gmv_l7d
    ,sum(case when local_date >= date_sub(${local_date},6) and is_win_day = 1 then treatment_imp_cnt_normal else 0 end) win_treatment_imp_cnt_l7d
    ,sum(case when local_date >= date_sub(${local_date},6) and is_win_day = 1 then treatment_gmv_normal else 0 end) win_treatment_gmv_l7d
    ,1.0000*sum(imp_cnt)/14 avg_imp_cnt_l14d
    ,sum(gmv)/14 avg_gmv_l14d
    ,1.0000*sum(cspu_imp_cnt)/14 avg_cspu_imp_cnt_l14d
    ,sum(cspu_gmv)/14 avg_cspu_gmv_l14d
    ,0.02*sum(case when local_date >= date_sub(${local_date},6) and is_win_day = 1 and imp_cnt_1d_uplift_pct<=0 then imp_cnt else 0 end) imp_cnt_extra_bonus
from traffic_raw_${grass_region_without_quote}
group by 1,2,3
;
--sql_divide_splitter--

create temporary view winner_l7d_uplift_${grass_region_without_quote} as
select model_id
    ,case when win_control_imp_cnt_l7d > 0 then GREATEST(1.0000*win_treatment_imp_cnt_l7d/win_control_imp_cnt_l7d-1,0)
        when win_treatment_imp_cnt_l7d > 0 then 1.0
    else 0.02 end as win_imp_cnt_uplift_pct
    ,case when win_control_gmv_l7d > 0 then GREATEST(1.0000*win_treatment_gmv_l7d/win_control_gmv_l7d-1,0)
          when win_treatment_gmv_l7d > 0 then 1.0
    else 0 end as win_gmv_uplift_pct
from traffic_aggr_${grass_region_without_quote}
;
--sql_divide_splitter--

create temporary view tbi_rcmd_imp_uplift_${grass_region_without_quote} as
select model_id
    , tbi_imp_cnt_uplift_pct
from (
      SELECT model_id
           , tbi_imp_cnt_uplift_pct
           , row_number() over(partition BY model_id ORDER BY cspu_k DESC, k DESC) AS rnk
      FROM traffic_aggr_${grass_region_without_quote} a
      INNER JOIN (
          select *
              from srdi_mart.dws_sr_data_warehouse_tc_pb_reward_tbi_uplift_dictionary_30d
          where grass_region = ${grass_region}
          and local_date = ${local_date}  -- 字典是每天滑动更新的，取当天的分区
      ) b
      ON a.avg_cspu_imp_cnt_l14d >= b.cspu_imp_cnt_pp
      and a.avg_imp_cnt_l14d >= b.imp_cnt_pp
  )x
where rnk = 1
;
--sql_divide_splitter--

create temporary view tbi_rcmd_gmv_uplift_${grass_region_without_quote} as
select model_id
     , tbi_gmv_uplift_pct
from (
     SELECT model_id
          , tbi_gmv_uplift_pct
          , row_number() over(partition BY model_id ORDER BY cspu_k DESC, k DESC) AS rnk
     FROM traffic_aggr_${grass_region_without_quote} a
     INNER JOIN (
         select *
         from srdi_mart.dws_sr_data_warehouse_tc_pb_reward_tbi_uplift_dictionary_30d
         where grass_region = ${grass_region}
           and local_date = ${local_date}
     ) b
     ON a.avg_cspu_gmv_l14d >= b.cspu_gmv_pp
     and a.avg_gmv_l14d >= b.gmv_pp
 )x
where rnk = 1
;
