create temporary view combine_uplift_${grass_region_without_quote} as
SELECT a.model_id
    ,shop_id
    ,item_id
    ,imp_cnt_l7d
    ,gmv_l7d
    ,least(ceil(win_imp_cnt_l7d*(1-1/(1+win_imp_cnt_uplift_pct)/(1+imp_cnt_control_uplift_pct))+imp_cnt_extra_bonus),win_imp_cnt_l7d)
        as win_imp_cnt_l7d_uplift
    ,least(win_gmv_l7d*(1-1/(1+win_gmv_uplift_pct)/(1+gmv_control_uplift_pct)),win_gmv_l7d)
        as win_gmv_l7d_uplift
    ,ceil(avg_imp_cnt_l14d*((1+tbi_imp_cnt_uplift_pct)*(1+imp_cnt_control_uplift_pct)-1)*7)  as tbi_rcmd_imp_cnt_l7d_uplift
    ,if(tbi_gmv_uplift_pct is null, 0, avg_gmv_l14d*((1+tbi_gmv_uplift_pct)*(1+gmv_control_uplift_pct)-1)*7) as tbi_rcmd_gmv_l7d_uplift

--  下列字段用于自测保存中间数据，正式表删除
    ,win_control_imp_cnt_l7d
    ,win_control_gmv_l7d
    ,win_treatment_imp_cnt_l7d
    ,win_treatment_gmv_l7d
    ,avg_imp_cnt_l14d
    ,avg_gmv_l14d
    ,avg_cspu_imp_cnt_l14d
    ,avg_cspu_gmv_l14d
    ,imp_cnt_extra_bonus

    ,win_imp_cnt_uplift_pct
    ,win_gmv_uplift_pct
    ,tbi_imp_cnt_uplift_pct
    ,tbi_gmv_uplift_pct
    ,imp_cnt_control_uplift_pct
    ,gmv_control_uplift_pct

    ,win_imp_cnt_l7d
    ,win_gmv_l7d
from traffic_aggr_${grass_region_without_quote} a
left join winner_l7d_uplift_${grass_region_without_quote} b
    on a.model_id = b.model_id
left join tbi_rcmd_imp_uplift_${grass_region_without_quote} c
    on a.model_id = c.model_id
left join tbi_rcmd_gmv_uplift_${grass_region_without_quote} d
    on a.model_id = d.model_id
left join(
    select imp_cnt_control_uplift_pct
        ,gmv_control_uplift_pct
        from srdi_mart.dws_sr_data_warehouse_tc_pb_reward_control_uplift_15d
    where grass_region = ${grass_region}
-- aa uplift 30d更新一次，取最大可用分区
    and local_date = data_infra.max_pt('srdi_mart.dws_sr_data_warehouse_tc_pb_reward_control_uplift_15d', 'local_date', "grass_region=${grass_region} and local_date<=${local_date}")
)e
on 1=1
;
--sql_divide_splitter--

create temporary view rebate_${grass_region_without_quote} as
select model_id,
    sum(net_item_rebate_by_shopee_amt) as item_rebate_local_l7d
from mp_order.dwd_order_item_all_ent_df__reg_s0_live
where grass_region in (${grass_region})
and date(create_datetime) between date_sub(${local_date},6) and ${local_date}
and grass_date >= date_sub(${local_date},6)
and tz_type = 'local'
and item_promotion_type_id = 323
and is_bi_excluded = 0
group by 1
;
--sql_divide_splitter--

insert overwrite table ${schema}.ads_sr_data_warehouse_tc_pb_reward_model_uplift_7d
partition (grass_region = ${grass_region},local_date = ${local_date})
select shop_id
    ,item_id
    ,a.model_id
    ,imp_cnt_l7d
    ,gmv_l7d*exchange_rate as gmv_l7d
    ,win_imp_cnt_l7d_uplift
    ,win_gmv_l7d_uplift*exchange_rate as win_gmv_l7d_uplift
    ,tbi_rcmd_imp_cnt_l7d_uplift
    ,tbi_rcmd_gmv_l7d_uplift*exchange_rate as tbi_rcmd_gmv_l7d_uplift

    ,win_control_imp_cnt_l7d
    ,win_control_gmv_l7d
    ,win_treatment_imp_cnt_l7d
    ,win_treatment_gmv_l7d
    ,avg_imp_cnt_l14d
    ,avg_gmv_l14d
    ,avg_cspu_imp_cnt_l14d
    ,avg_cspu_gmv_l14d
    ,imp_cnt_extra_bonus
    ,win_imp_cnt_uplift_pct
    ,win_gmv_uplift_pct
    ,tbi_imp_cnt_uplift_pct
    ,tbi_gmv_uplift_pct
    ,imp_cnt_control_uplift_pct
    ,gmv_control_uplift_pct
    ,win_imp_cnt_l7d
    ,win_gmv_l7d

    ,coalesce(item_rebate_local_l7d,0) item_rebate_local_l7d
from combine_uplift_${grass_region_without_quote} a
left join (
    select max(exchange_rate) as exchange_rate
    from mp_order.dim_exchange_rate__reg_s0_live
    where grass_region in (${grass_region})
      and grass_date = ${local_date}
)b
on 1=1
left join rebate_${grass_region_without_quote} c
on a.model_id = c.model_id
;
